// Boxing - value type to reference type
int number = 42;
object boxed = number;  // Boxing (heap allocation)

// Unboxing - reference type to value type
int unboxed = (int)boxed;  // Unboxing (type check)

// Avoid with generics
List<int> numbers = new List<int>();
numbers.Add(42);  // No boxing!
